@IsTest(SeeAllData=false) private class ResultOutputObservation{
@IsTest static void rdto01(){Map<String,Object> payload=new Map<String,Object>();try{Invocable.Action.Result dto=(Invocable.Action.Result)JSON.deserialize('{"action":null,"errors":null,"success":true,"outputParameters":{}}',Invocable.Action.Result.class);payload.put('success',dto.isSuccess());Map<String,Object> held=dto.getOutputParameters();payload.put('initialEmpty',held.isEmpty());Account input=new Account(Name='initial',Description='retained');dto.getOutputParameters().putAll(new Map<String,Object>{'entry'=>input});Invocable.Action.Result alias=dto;List<Invocable.Action.Result> results=new List<Invocable.Action.Result>{dto};Account output=(Account)results[0].getOutputParameters().get('entry');payload.put('sameResult',alias===dto);payload.put('sameMap',held===alias.getOutputParameters());payload.put('sameRecord',input===output);input.Name='changed';input.Description=null;payload.put('name',output.Name);payload.put('descriptionNull',output.Description==null);held.put('nil',null);payload.put('nullKeyPresent',alias.getOutputParameters().containsKey('nil'));payload.put('nullValue',alias.getOutputParameters().get('nil')==null);alias.getOutputParameters().clear();payload.put('clearShared',held.isEmpty());payload.put('otherFieldsNull',dto.getErrors()==null&&dto.getAction()==null&&dto.getInvocationParameters()==null);}catch(Exception fault){payload.put('exceptionType',fault.getTypeName());payload.put('exceptionMessage',fault.getMessage());}System.assert(false,'RESULT_DTO_RESULT|RDTO01|'+JSON.serialize(payload));}
@IsTest static void rdto02(){Map<String,Object> payload=new Map<String,Object>();try{Invocable.Action.Result dto=(Invocable.Action.Result)JSON.deserialize('{"action":null,"errors":[{"code":"SYNTHETIC","message":"declined"}],"success":false,"outputParameters":{}}',Invocable.Action.Result.class);payload.put('success',dto.isSuccess());payload.put('outputsEmpty',dto.getOutputParameters().isEmpty());payload.put('errorCount',dto.getErrors().size());payload.put('code',dto.getErrors()[0].getCode());payload.put('message',dto.getErrors()[0].getMessage());Invocable.Action.Error item=(Invocable.Action.Error)JSON.deserialize('{"code":"SECOND","message":"second detail"}',Invocable.Action.Error.class);payload.put('standaloneCode',item.getCode());payload.put('standaloneMessage',item.getMessage());payload.put('otherFieldsNull',dto.getAction()==null&&dto.getInvocationParameters()==null);}catch(Exception fault){payload.put('exceptionType',fault.getTypeName());payload.put('exceptionMessage',fault.getMessage());}System.assert(false,'RESULT_DTO_RESULT|RDTO02|'+JSON.serialize(payload));}
@IsTest static void rdto03(){Map<String,Object> payload=new Map<String,Object>();try{Invocable.Action.Result empty=(Invocable.Action.Result)JSON.deserialize('{}',Invocable.Action.Result.class);payload.put('successNull',empty.isSuccess()==null);payload.put('outputsNull',empty.getOutputParameters()==null);payload.put('errorsNull',empty.getErrors()==null);payload.put('invocationNull',empty.getInvocationParameters()==null);payload.put('actionNull',empty.getAction()==null);try{Invocable.Action.Result rejected=(Invocable.Action.Result)JSON.deserialize('{"success":true,"outputParameters":{"value":7}}',Invocable.Action.Result.class);payload.put('populatedAccepted',true);}catch(Exception fault){payload.put('rejectType',fault.getTypeName());payload.put('rejectMessage',fault.getMessage());}}catch(Exception fault){payload.put('exceptionType',fault.getTypeName());payload.put('exceptionMessage',fault.getMessage());}System.assert(false,'RESULT_DTO_RESULT|RDTO03|'+JSON.serialize(payload));}
}

